public class ItemFolders
{
    [JsonPropertyName("folders")]
    public List<ItemFolder>? Folders { get; set; }

    /// <summary>Item id → the id of the folder it is filed in. An item not listed is in no folder.</summary>
    [JsonPropertyName("entries")]
    public Dictionary<string, string>? Entries { get; set; }
}

public class ItemFoldersCreateBody
{
    /// <summary>The workspace (a uuid).</summary>
    [JsonPropertyName("workspaceId")]
    public string? WorkspaceId { get; set; }

    /// <summary>One of the constants of ItemFolderKind.</summary>
    [JsonPropertyName("kind")]
    public string? Kind { get; set; }

    /// <summary>Whitespace is folded; at most 120 characters.</summary>
    [JsonPropertyName("name")]
    public string? Name { get; set; }

    /// <summary>The folder to create it in; omitted, at the top.</summary>
    [JsonPropertyName("parentId")]
    public string? ParentId { get; set; }
}

public class ItemFoldersCreateResponse
{
    [JsonPropertyName("success")]
    public bool? Success { get; set; }

    [JsonPropertyName("data")]
    public ItemFoldersCreateResponseData? Data { get; set; }
}

public class ItemFoldersCreateResponseData
{
    [JsonPropertyName("folder")]
    public ItemFolder? Folder { get; set; }
}

public class ItemFoldersDeleteResponse
{
    [JsonPropertyName("success")]
    public bool? Success { get; set; }

    [JsonPropertyName("data")]
    public ItemFoldersDeleteResponseData? Data { get; set; }
}

public class ItemFoldersDeleteResponseData
{
    [JsonPropertyName("deleted")]
    public bool? Deleted { get; set; }
}

public class ItemFoldersListQuery
{
    /// <summary>The workspace (a uuid).</summary>
    [JsonPropertyName("workspaceId")]
    public string? WorkspaceId { get; set; }

    /// <summary>One of the constants of ItemFolderKind.</summary>
    [JsonPropertyName("kind")]
    public string? Kind { get; set; }
}

public class ItemFoldersListResponse
{
    [JsonPropertyName("success")]
    public bool? Success { get; set; }

    [JsonPropertyName("data")]
    public ItemFolders? Data { get; set; }
}

public class ItemFoldersMoveBody
{
    /// <summary>The workspace (a uuid).</summary>
    [JsonPropertyName("workspaceId")]
    public string? WorkspaceId { get; set; }

    /// <summary>One of the constants of ItemFolderKind.</summary>
    [JsonPropertyName("kind")]
    public string? Kind { get; set; }

    /// <summary>The items' ids (uuids); 500 at most.</summary>
    [JsonPropertyName("itemIds")]
    public List<string>? ItemIds { get; set; }

    /// <summary>
    /// The folder; null for no folder.
    /// <para/>
    /// Required; null is sent as null.
    /// </summary>
    [JsonPropertyName("folderId")]
    [JsonIgnore(Condition = JsonIgnoreCondition.Never)]
    public string? FolderId { get; set; }
}

public class ItemFoldersMoveResponse
{
    [JsonPropertyName("success")]
    public bool? Success { get; set; }

    [JsonPropertyName("data")]
    public ItemFoldersMoveResponseData? Data { get; set; }
}

public class ItemFoldersMoveResponseData
{
    [JsonPropertyName("moved")]
    public double? Moved { get; set; }
}

public class ItemFoldersUpdateBody
{
    /// <summary>Whitespace is folded; at most 120 characters.</summary>
    [JsonPropertyName("name")]
    public string? Name { get; set; }

    /// <summary>The folder to move it into; null or empty for the top.</summary>
    [JsonPropertyName("parentId")]
    public string? ParentId { get; set; }
}

public class ItemFoldersUpdateResponse
{
    [JsonPropertyName("success")]
    public bool? Success { get; set; }

    [JsonPropertyName("data")]
    public ItemFoldersUpdateResponseData? Data { get; set; }
}

public class ItemFoldersUpdateResponseData
{
    [JsonPropertyName("folder")]
    public ItemFolder? Folder { get; set; }
}
